 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The three adjacent cells at the top form the color key.
    key_row = next(r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 3)
    cols = [c for c, v in enumerate(grid[key_row]) if v]
    colors = [grid[key_row][c] for c in cols]
    for c, color in zip(cols, colors):
        others = [(r, x) for r in range(h) for x in range(w)
                  if grid[r][x] == color and (r, x) not in [(key_row, cc) for cc in cols]]
        if others:
            # Join the keyed cell to its matching marker with an orthogonal bend.
            r, x = others[0]
            for rr in range(min(key_row, r), max(key_row, r) + 1):
                out[rr][c] = color
            for cc in range(min(c, x), max(c, x) + 1):
                out[r][cc] = color
        else:
            # A color without a marker continues down to the bottom edge.
            for rr in range(key_row, h):
                out[rr][c] = color
    return out
